add(70,'길이 L,선밀도 ρ인 다이빙대 끝에 질량 m의 사람이 있다. EI y″=mg(L−x)+(ρg/2)(L−x)², g<0에서 (a)곡선,(b)끝의 처짐 거리를 구하라.','For a diving board of length L,densityρ,and end mass m,suppose EI y″=mg(L−x)+(ρg/2)(L−x)² with g<0.Find(a)the curve and(b)end deflection.', [('고정단에서 f(0)=f′(0)=0이다. 우변을 전개하고 두 번 적분해 상수를 이 경계조건으로 정한다.','At the clamped end,f(0)=f′(0)=0.Expand the right side,integrate twice,and use these boundary conditions.'),F(r'f(x)={g\over EI}\left[m\left({Lx^2\over2}-{x^3\over6}\right)+\rho\left({L^2x^2\over4}-{Lx^3\over6}+{x^4\over24}\right)\right]'),F(r'f(L)={g\over EI}\left({mL^3\over3}+{\rho L^4\over8}\right)'),('g<0이므로 끝의 높이는 음수이며 아래로 처진 거리는 −f(L)이다.','Since g<0,the tip height is negative;the downward distance is−f(L).')],m(r'\text{deflection}={-g\over EI}\left({mL^3\over3}+{\rho L^4\over8}\right)'),parts=list('ab'))
add(71,'한계비용이1.92−0.002x달러/개이고 1개 생산비가562달러일 때 100개 생산비를 구하라.','Marginal cost is1.92−0.002x dollars/item and one item costs562 dollars.Find the cost of100 items.',[F(r'C(x)=1.92x-0.001x^2+K'),F(r'K=562-1.92+0.001=560.081'),F(r'C(100)=192-10+560.081=742.081')],'약 $742.08.','Approximately $742.08.')
add(72,'길이1m 막대의 선밀도는 ρ(x)=1/√x g/cm이며 x는 cm이다. 전체 질량을 구하라.','A1m rod has densityρ(x)=1/√x g/cm,with x in centimeters.Find total mass.', [('길이를100cm로 바꾸고,0의 특이점에서는 양의 ε에서 시작한 극한을 취한다.','Convert the length to100cm;handle the singularity at0 by starting atε>0 and taking a limit.'),F(r'M=\lim_{\varepsilon\to0^+}\int_{\varepsilon}^{100}x^{-1/2}\,dx=\lim_{\varepsilon\to0^+}(20-2\sqrt\varepsilon)=20\ \mathrm{g}')],m(r'20\ \mathrm{g}'))
add(73,'지면500m 위 빗방울의 초기 하강속도는10m/s,하강가속도는0≤t≤10에서9−0.9t,그 뒤0이다. 낙하시간을 구하라.','A raindrop starts500m above ground with downward speed10m/s.Its downward acceleration is9−0.9t for0≤t≤10,and0 thereafter.Find fall time.',[F(r'v(t)=10+9t-0.45t^2,\quad d(t)=10t+4.5t^2-0.15t^3\quad(0\le t\le10)'),F(r'v(10)=55,\quad d(10)=400'),('10초 뒤에는55m/s를 유지하고 남은100m를 이동한다.','After10s it keeps speed55m/s through the remaining100m.'),F(r'T=10+100/55=130/11\approx11.818\ \mathrm{s}')],m(r'130/11\ \mathrm{s}\approx11.818\ \mathrm{s}'))
add(74,'50mi/h로 가던 차가22ft/s²로 일정하게 감속할 때 정지거리를 구하라.','Find stopping distance from50mi/h with constant deceleration22ft/s².',[F(r'v_0=50(5280/3600)=220/3\ \mathrm{ft/s}'),F(r'0=v_0^2-44d\Longrightarrow d=1100/9\approx122.22\ \mathrm{ft}')],m(r'122.22\ \mathrm{ft}'))
add(75,'5초 동안30mi/h에서50mi/h로 증가시키는 일정 가속도를 구하라.','Find constant acceleration from30mi/h to50mi/h in5s.',[F(r'a={(50-30)(5280/3600)\over5}={88\over15}\ \mathrm{ft/s^2}')],m(r'a\approx5.867\ \mathrm{ft/s^2}'))
add(76,'감속도16ft/s²로 제동하여200ft를 미끄러진 뒤 멈춘 차의 초기속력을 구하라.','A car stops over200ft under constant deceleration16ft/s².Find initial speed.',[F(r'0=v_0^2-2(16)(200)'),F(r'v_0=80\ \mathrm{ft/s}=600/11\ \mathrm{mi/h}')],m(r'80\ \mathrm{ft/s}\approx54.55\ \mathrm{mi/h}'))
add(77,'100km/h로 가는 차가80m 앞에서 멈추려면 필요한 일정 감속도를 구하라.','Find constant deceleration needed to stop within80m from100km/h.',[F(r'v_0=250/9\ \mathrm{m/s},\quad0=v_0^2+2a(80)'),F(r'a=-{3125\over648}\approx-4.823\ \mathrm{m/s^2}')],'감속 크기는 최소4.823m/s²이다.','Deceleration magnitude must be at least4.823m/s².')
add(78,'로켓이 정지 출발하여 첫3초 a=60t(ft/s²),그 뒤14초 자유비행한다. 낙하산이 열려5초 동안 속도가 선형으로−18ft/s가 되고 이후 그 속도로 내려온다. (a)s,v와 그래프,(b)최고점,(c)착지시간을 구하라.','A rocket starts from rest with a=60t(ft/s²)for3s,then flies freely14s.A parachute then changes velocity linearly to−18ft/s over5s;that speed persists.Find(a)s,v and plots,(b)maximum height,and(c)landing time.',[F(r'v(t)=\begin{cases}30t^2&0\le t\le3\\270-32(t-3)&3\le t\le17\\-178+32(t-17)&17\le t\le22\\-18&22\le t\le410/9\end{cases}'),F(r's(t)=\begin{cases}10t^3&0\le t\le3\\270+270(t-3)-16(t-3)^2&3\le t\le17\\914-178(t-17)+16(t-17)^2&17\le t\le22\\424-18(t-22)&22\le t\le410/9\end{cases}'),('각 구간 경계에서 위치와 속도를 연속으로 맞췄다. 지상 출발을 s(0)=0으로 두었다.','Position and velocity match at every join,with ground launch s(0)=0.'),F(r'v=0\Longrightarrow t=3+270/32=183/16=11.4375'),F(r's_{\max}=22545/16=1409.0625\ \mathrm{ft}'),F(r's=0\Longrightarrow t=22+424/18=410/9\approx45.556\ \mathrm{s}')],m(r'(b)\ t=11.4375\mathrm{s},\ s=1409.0625\mathrm{ft};\quad(c)\ t=45.556\mathrm{s}'),parts=list('abc'))
add(79,'열차의 가감속도 크기는2.4ft/s²,최고속력180mi/h이다. (a)정지에서 최고속력 도달 후20분 순항한 거리,(b)출발·정지 포함20분 최대거리,(c)60mi 역간 최소시간,(d)37.5분 역간 거리를 구하라.','A train accelerates/decelerates at2.4ft/s² with top speed180mi/h.Find(a)distance after acceleration plus20min cruising,(b)maximum rest-to-rest distance in20min,(c)minimum rest-to-rest time over60mi,(d)station distance for a37.5min fastest trip.',[F(r'V=264\ \mathrm{ft/s},\quad t_a=V/2.4=110\ \mathrm{s},\quad d_a=Vt_a/2=14520\ \mathrm{ft}=2.75\ \mathrm{mi}'),F(r'(a)\ d=2.75+180(20/60)=62.75\ \mathrm{mi}'),F(r'(b)\ d=V(1200-110)=287760\ \mathrm{ft}=54.5\ \mathrm{mi}'),('출발과 정지의 삼각형 면적 두 개를 합치면 최고속력으로110초 달린 면적 하나만큼 줄어든다.','Together,the acceleration and braking triangles lose the area of110s at full speed.'),F(r'(c)\ T={60(5280)\over264}+110=1310\ \mathrm{s}=21\mathrm{min}\ 50\mathrm{s}'),F(r'(d)\ d={264(2250-110)\over5280}=107\ \mathrm{mi}')],m(r'(a)62.75\mathrm{mi};\ (b)54.5\mathrm{mi};\ (c)1310\mathrm{s};\ (d)107\mathrm{mi}'),parts=list('abcd'))
